package main

import (
	"strings"
	"testing"
)

func TestNativeLinkProjectionDoesNotHideWrongIdentity(t *testing.T) {
	f := Fixture{Run: "0c4c2fd57dc54308b618415dbb06e22c", Requests: 100}
	// Captured from the native 1.2.0 SQL response, not generated by the reader.
	actual := `[{"context":{"traceId":"6dabf18866d43429bea9ec4f07e83dd7","spanId":"dffac1676cb54741","traceFlags":1,"traceState":""},"relationship":"previous-checkout","droppedAttributesCount":0}]`
	expected := f.span(99, 0).Links
	if err := checkOpenObserveLinks(expected, actual); err != nil {
		t.Fatal(err)
	}
	wrong := strings.Replace(actual, "dffac1676cb54741", "0000000000000000", 1)
	if err := checkOpenObserveLinks(expected, wrong); err == nil {
		t.Fatal("wrong link identity passed despite unchanged counts")
	}
}
